async function postToSlack(text, channelId, slackApiToken) {
  // **Helpfulness (High):** Explicitly handles API interaction and error handling for clarity.
  try {
    const response = await fetch(`https://slack.com/api/chat.postMessage`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${slackApiToken}` // Secure token handling
      },
      body: JSON.stringify({
        channel: channelId, 
        text: text,
        // Optional: Add more Slack message parameters (e.g., thread_ts, blocks) for richer posts
      })
    });

    if (!response.ok) {
      throw new Error(`Slack API Error: ${await response.text()} (Status: ${response.status})`); 
      // **Helpfulness:** Provides informative error messages.
    }

    const data = await response.json();
    console.log(`Message posted successfully to channel ${channelId}!`); 
    // **Verbosity (Medium):** Confirms successful posting with channel info.

    return data; // Return API response for further use if needed

  } catch (error) {
    console.error("Error posting to Slack:", error);
    // **Helpfulness:**  Robust error logging for debugging.
    throw error; // Re-throw to allow caller to handle critically
  }
}
```

