#include <iostream>
#include <limits>

using namespace std;

// Recursive Fibonacci function with error handling
int fibonacci(int a, int b, int n) {
    if (n <= 0) return 0;  // Base case: Zero or negative terms yield 0
    else if (n == 1) return a; // Base case: First term is 'a'
    else if (n == 2) return b; // Base case: Second term is 'b'
    else {
        int result = a + fibonacci(b, a + b, n - 1);
        return result; 
    }
}

