public double CalculatePurchaseTotal(double carPrice, double clothesPrice, double bookPrice)
{
    double combinedCost = clothesPrice + bookPrice;

    // Direct Calculation if Constraint Holds
    if (carPrice >= 2 * combinedCost)
    {
        return carPrice + clothesPrice + bookPrice;
    }
    else 
    {
        // Adjustment Loop (Example: Incrementing by 100 until constraint met)
        while (carPrice < 2 * combinedCost)
        {
