   func generateInsightfulStatement(profile: UserProfile) -> String {
       var statement = "Based on your interactions..."

       // 1. Click Emphasis:
       if profile.clickedProducts.count > 2 {
           let topClicks = profile.clickedProducts.prefix(2).joined(separator: " and ")
           statement +=  " a strong interest in \(topClicks) is evident."
       }

       // 2. Color Influence:
       switch profile.preferredColor {
       case "blue": statement += " ...leaning towards products with a calming, modern aesthetic."
       case "minimalistic": statement += " ...favoring sleek, uncluttered designs."
       default: statement += " ...showing openness to diverse visual styles."
       }

