import Foundation

func generateSkiSnowComparison(sportPreference: String) -> [[String]] {
    var comparisonData: [[String]] = [] //  Excel-compatible data structure

    // Header Row (Fixed)
    comparisonData.append(["Factor", "Skiing", "Snowboarding"])

