        "Terrain Variety": sportPreference == "skiing" ? "Excellent Across All Types" : "Adaptable, excels in Powder & Parks",
        "Trick Opportunities": sportPreference == "snowboarding" ? "Extensive, Culture Driven" : "Possible but Less Specialized"
    ]

    //  Populate Rows with Formatted Values
    for (factor, value) in factors {
        comparisonData.append([factor, value])
    }

    return comparisonData
}

