import { Injectable } from '@nestjs/common';
import { AuthGuard, ExecutionContext, Reflector } from '@nestjs/common';
import { PrismaService } from './prisma.service';
import { Role } from './entities/user.entity';

@Injectable()
export class RolesGuard extends AuthGuard {
  constructor(private prisma: PrismaService, private reflector: Reflector) {}

  asynccanActivate(context: ExecutionContext): Promise<boolean | void> {
    const requiredRoles = this.reflector.get<Role[]>('roles', context.getHandler());
    if (!requiredRoles) return true; 

    const request = context.switchToHttp().getRequest();
    const user = request.user;
    return !!user && user.role?.some(userRole => requiredRoles.includes(userRole));
  }
}

