function geocodeAndPopulate(spreadsheetId, sheetName, placeColumnName, latColumn, lngColumn) {
  // 1. Access Spreadsheet and Sheet
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(sheetName);

  // 2. Fetch Place Names & Iterate
  const dataRange = sheet.getRange(placeColumnName); // Assuming your place names are in a continuous column
  const placeValues = dataRange.getValues().flat(); // Extract place names into an array

  for (let i = 0; i < placeValues.length; i++) {
    const placeName = placeValues[i];
    const geocodingResult = geocodeAddress(placeName); // Call geocoding function (see below)

    // 3. Store Lat/Long if Successful
    if (geocodingResult.status === 'OK') {
      const lat = geocodingResult.results[0].geometry.location.lat();
      const lng = geocodingResult.results[0].geometry.location.lng();
      sheet.getRange(i + 2, latColumn).setValue(lat);  // +2 to skip header row (adjust as needed)
      sheet.getRange(i + 2, lngColumn).setValue(lng);
    } else {
      // Handle geocoding errors (e.g., log, set error marker in cell)
      console.log(`Geocoding error for "${placeName}": ${geocodingResult.status}`);
      sheet.getRange(i + 2, latColumn).setValue('Geocoding Error'); 
    }
  }
}

// --- Helper Function: geocodeAddress(placeName) ---
function geocodeAddress(placeName) {
  const geocoder = new google.maps.Geocoder();
  const request = { address: placeName };
  return geocoder.geocode(request);
}
```

