```php
<?php

function smart_sort_array(array $set, string $order = 'asc'): array {
    /**
     * Sorts an array of associative arrays (with 'name', 'address', 'age' keys) based on 'age', respecting ascending/descending order.
     *
     * @param array $set  The input array of associative sub-arrays.
     * @param string $order 'asc' (default) for ascending, 'desc' for descending sort by age.
     * @return array The sorted array.
     */
    usort($set, function($a, $b) use ($order) {
        $comparison = $order === 'asc' ? 1 : -1; // Determine comparison direction
        return $comparison * ($a['age'] - $b['age']); 
    });
    return $set;
}

// Example Usage:
$data = [
    ['name' => 'Alice', 'address' => '123 Main', 'age' => 25],
    ['name' => 'Bob', 'address' => '456 Oak', 'age' => 30],
    ['name' => 'Charlie', 'address' => '789 Pine', 'age' => 20]
];

// Ascending sort (default)
$sortedAsc = smart_sort_array($data);
echo "Ascending:\n"; var_dump($sortedAsc);

// Descending sort
$sortedDesc = smart_sort_array($data, 'desc');
echo "\nDescending:\n"; var_dump($sortedDesc);
```

